examples.code:
Open-OfficeVisio -Path .\Diagrams\Network.vsdx {
    VisioPage 'DR site' {
        VisioRectangle -Key fw -Text 'Firewall' -X 1.5in -Y 4in
        VisioRectangle -Key core -Text 'Core switch' -X 4.5in -Y 4in
        VisioRectangle -Key hosts -Text 'VM hosts' -X 7.5in -Y 4in
        VisioConnector -From fw -To core
        VisioConnector -From core -To hosts
    }
}

$diagram = Open-OfficeVisio -Path .\Diagrams\Network.vsdx
Add-OfficeVisioPage -Document $diagram -Name 'Change 4711' {
    VisioTextBox 'Planned for 14 November' -X 1in -Y 7.5in
}
Save-OfficeVisio -Document $diagram -Path .\Diagrams\Network-Change-4711.vsdx -Show

$devices = Import-OfficeCsv -Path .\Data\Network-Devices.csv
New-OfficeVisio -Path .\Diagrams\Sites.vsdx -PageName 'Index' {
    VisioTextBox 'One page per site' -X 4.25in -Y 7.5in -Width 6in
    foreach ($site in $devices | Group-Object Site) {
        VisioPage $site.Name -Width 11in -Height 8.5in {
            $x = 1.5
            foreach ($device in $site.Group) {
                VisioRectangle -Key $device.Name -Text "$($device.Name)`n$($device.Role)" -X "$($x)in" -Y 4in
                $x += 2.5
            }
        }
    }
}

New-OfficeVisio -Path .\Link.vsdx {
    VisioRectangle -Key client -Text 'Client' -X 1.5in -Y 4in
    VisioRectangle -Key server -Text 'Server' -X 5in -Y 4in
    VisioConnector -From client -To server
}

New-OfficeVisio -Path .\Tier.vsdx {
    VisioRectangle -Key api -Text 'API' -X 2in -Y 4in
    VisioRectangle -Key worker -Text 'Worker' -X 4.5in -Y 4in
    VisioContainer -Key app -Text 'Application tier' -ShapeId api, worker
}

New-OfficeVisio -Path .\Aligned.vsdx {
    VisioRectangle -Key a -Text 'Plan' -X 1.5in -Y 4in
    VisioRectangle -Key b -Text 'Build' -X 4in -Y 4.3in
    VisioRectangle -Key c -Text 'Run' -X 6.5in -Y 3.8in
    VisioLayout -ShapeId a, b, c -VerticalAlignment Middle -Distribute Horizontal
}

$servers = Import-OfficeCsv -Path .\Data\Servers.csv
New-OfficeVisio -Path .\Diagrams\Server-Grid.vsdx {
    foreach ($server in $servers) {
        VisioRectangle -Key $server.Name -Text $server.Name
    }
    VisioLayout -ShapeId $servers.Name -Grid -Columns 3 -HorizontalSpacing 0.5in -VerticalSpacing 0.4in
}

New-OfficeVisio -Path .\Diagrams\Layers.vsdx {
    VisioRectangle -Key ui -Text 'User interface'
    VisioRectangle -Key logic -Text 'Business logic'
    VisioRectangle -Key data -Text 'Data access'
    VisioLayout -ShapeId ui, logic, data -VerticalStack -VerticalSpacing 0.3in
}

Get-ChildItem -Path .\Stencils -Filter *.vssx | ForEach-Object {
    $gallery = @{
        LiteralPath = $_.FullName
        OutputDirectory = Join-Path .\StencilPreview $_.BaseName
        Title = "$($_.BaseName) stencils"
        ThumbnailWidth = 240
        ThumbnailHeight = 180
    }
    Export-OfficeVisioStencilPreviewGallery @gallery -PassThru
}

$visual = Get-Content -Path .\Topology.cfx.json -Raw | ConvertTo-OfficeVisioVisual -PageName 'Topology' -UseNaturalPageSize
$visual.Report
Add-OfficeVisioPage -Document $visual.Document -Name 'Notes' {
    VisioTextBox 'Generated from the monitoring export on 26 October 2026' -X 1in -Y 7.5in -Width 6in
}
Save-OfficeVisio -Document $visual.Document -Path .\Diagrams\Topology.vsdx

$phases = [ordered]@{
    Discovery = @{ 'Stakeholder interviews' = 4; 'Requirements sign-off' = 1 }
    Delivery = @{ 'Build' = 15; 'User acceptance testing' = 5 }
}
New-OfficeProject -Path .\Plans\Website.mpp -Name 'Website redesign' -StartDate '2026-11-09' {
    foreach ($phase in $phases.Keys) {
        $summary = Add-OfficeProjectTask $phase -Summary -PassThru
        foreach ($task in $phases[$phase].GetEnumerator()) {
            Add-OfficeProjectTask $task.Key -DurationDays $task.Value -Parent $summary
        }
    }
    Add-OfficeProjectTask 'Go live' -DurationDays 0
}

$team = Import-OfficeCsv -Path .\Data\Team.csv
New-OfficeProject -Path .\Plans\Migration.mpp -Name 'Mail migration' {
    foreach ($member in $team) {
        Add-OfficeProjectResource $member.Name -StandardRate ([decimal]$member.HourlyRate)
    }
}

$project = Open-OfficeProject -Path .\Plans\Website.mpp -ReadOnly
$view = Get-OfficeProjectView -Document $project -Kind Gantt
foreach ($file in 'Gantt.pdf', 'Gantt.xlsx', 'Gantt.pptx') {
    Export-OfficeProjectReport -View $view -Path (Join-Path .\Reports $file) -NoClobber -PassThru
}

$tasks = Import-OfficeCsv -Path .\Data\Tracker-Tasks.csv |
    ConvertTo-OfficeProjectTable -Kind Tasks -ColumnMap @{ Uid = 'Id'; Name = 'Title' }
$resources = Import-OfficeCsv -Path .\Data\Tracker-People.csv |
    ConvertTo-OfficeProjectTable -Kind Resources -ColumnMap @{ Uid = 'Id'; Name = 'FullName' }

$assets = Import-OfficeCsv -Path .\Data\Assets.csv -InferSchema
New-OfficeAccess -Path .\Data\Assets.accdb -Title 'IT assets' {
    AccessTable Assets {
        AccessColumn Id -Type AutoNumber
        AccessColumn AssetTag -MaxLength 20
        AccessColumn Model -MaxLength 120
        AccessColumn PurchaseDate -Type DateTime
        AccessColumn Cost -Type Currency
        $assets | AccessRow
    }
}

New-OfficeAccess -Path .\Data\Orders.accdb -Title 'Orders' {
    AccessTable Customers {
        AccessColumn CustomerId -Type AutoNumber
        AccessColumn Name -MaxLength 100
    }
    AccessTable Orders {
        AccessColumn OrderId -Type AutoNumber -AutoNumberSeed 1000
        AccessColumn CustomerId -Type Int32
        AccessColumn Total -Type Currency
    }
}

New-OfficeAccess -Path .\Data\Prices.accdb {
    AccessTable Prices {
        AccessColumn Id -Type AutoNumber
        AccessColumn Sku -MaxLength 30
        AccessColumn Description -Type LongText
        AccessColumn UnitPrice -Type Decimal -Precision 18 -Scale 4
        AccessColumn ValidFrom -Type DateTime
    }
}

New-OfficeAccess -Path .\Data\Services.accdb -Title 'Service inventory' {
    AccessTable Services {
        AccessColumn Name -MaxLength 128
        AccessColumn DisplayName -MaxLength 255
        AccessColumn Status -MaxLength 20
        Get-Service | Select-Object Name, DisplayName, @{ Name = 'Status'; Expression = { "$($_.Status)" } } | AccessRow
    }
}

$database = Open-OfficeAccess -Path .\Data\Sales.accdb
New-OfficeMarkdown -Path .\Docs\Sales-Schema.md -Force {
    MarkdownHeading 'Sales database schema'
    foreach ($table in Get-OfficeAccessTable -Document $database -Name Customers, Orders) {
        MarkdownHeading $table.Name -Level 2
        MarkdownTable -InputObject ($table.Columns | Select-Object Name, DataType, MaxLength)
    }
}
Close-OfficeAccess -Document $database

$options = New-OfficeEmailReaderOptions -NoAttachmentContent
Get-ChildItem -Path .\Mail -Include *.msg, *.eml -Recurse | ForEach-Object {
    $mail = Open-OfficeEmail -LiteralPath $_.FullName -Options $options
    [pscustomobject]@{
        File = $_.Name
        From = "$($mail.From)"
        Subject = $mail.Subject
        Date = $mail.Date
        Attachments = $mail.Attachments.Count
    }
} | Export-OfficeExcel -Path .\Reports\Mail-Summary.xlsx

Get-OfficeConfluencePage -Session $session -SpaceId 98765 | ForEach-Object {
    $markdown = Get-OfficeConfluencePage -Session $session -PageId $_.Id -As Markdown
    $markdown.Value | Set-Content -Path (Join-Path .\Backup "$($_.Id).md") -Encoding utf8
}

Get-OfficeConfluencePage -Session $session -SpaceId 98765 |
    Where-Object Title -like 'Daily status 2026-09-*' |
    ForEach-Object { Remove-OfficeConfluencePage -Session $session -PageId $_.Id -Confirm }
